1	//! Value numbering based common subexpression elimination.
2	//! Reference: Value Driven Redundancy Elimination - Loren Taylor Simpson.
3	
4	use core::panic;
5	use itertools::Itertools;
6	use rustc_hash::{FxHashMap, FxHashSet, FxHasher};
